#!/usr/bin/env node
// npm run build:icons: renders the mark in src/assets/icon.ts to PNG with resvg (a pinned dev dependency) and writes
// src/assets/icons.ts, which the Worker serves (it has no static-assets binding):
//
//   /favicon.ico            an ICO holding 32 and 48 px PNGs of the rounded tile
//   /apple-touch-icon.png   180 px, full bleed: iOS and iPadOS round the corners themselves
//
// `--check` writes nothing and fails when the committed module differs from a fresh rendering; the tests run it too.
import { readFile, writeFile } from 'node:fs/promises'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { Resvg } from '@resvg/resvg-js'
import { markSvg } from '../src/assets/icon.ts'

const gatewayDir = resolve(dirname(fileURLToPath(import.meta.url)), '..')
export const ICONS_MODULE = join(gatewayDir, 'src', 'assets', 'icons.ts')

export function renderPng(svg, size) {
  const resvg = new Resvg(svg, { fitTo: { mode: 'width', value: size }, font: { loadSystemFonts: false } })
  return resvg.render().asPng()
}

/** An ICO file that wraps PNG images (supported by every browser that reads favicon.ico). */
export function icoFile(images) {
  const directory = Buffer.alloc(6 + 16 * images.length)
  directory.writeUInt16LE(0, 0) // reserved
  directory.writeUInt16LE(1, 2) // 1: icon
  directory.writeUInt16LE(images.length, 4)
  let offset = directory.length
  images.forEach(({ size, png }, index) => {
    const entry = 6 + 16 * index
    directory.writeUInt8(size >= 256 ? 0 : size, entry) // width, 0 meaning 256
    directory.writeUInt8(size >= 256 ? 0 : size, entry + 1) // height
    directory.writeUInt8(0, entry + 2) // no palette
    directory.writeUInt8(0, entry + 3) // reserved
    directory.writeUInt16LE(1, entry + 4) // colour planes
    directory.writeUInt16LE(32, entry + 6) // bits per pixel
    directory.writeUInt32LE(png.length, entry + 8)
    directory.writeUInt32LE(offset, entry + 12)
    offset += png.length
  })
  return Buffer.concat([directory, ...images.map(({ png }) => png)])
}

export function iconsModule() {
  const tile = markSvg()
  const ico = icoFile([32, 48].map((size) => ({ size, png: renderPng(tile, size) })))
  const appleTouch = renderPng(markSvg({ radius: 0 }), 180)
  return [
    '// Generated by `npm run build:icons` from src/assets/icon.ts (rendered with resvg): do not edit.',
    '',
    '/** /favicon.ico: 32 and 48 px PNGs of the mark, base64. */',
    `export const FAVICON_ICO_BASE64 = '${ico.toString('base64')}'`,
    '',
    '/** /apple-touch-icon.png: 180 px, base64. */',
    `export const APPLE_TOUCH_ICON_BASE64 = '${appleTouch.toString('base64')}'`,
    '',
  ].join('\n')
}

async function main() {
  const fresh = iconsModule()
  if (process.argv.includes('--check')) {
    if (fresh === await readFile(ICONS_MODULE, 'utf8').catch(() => '')) return
    console.error('src/assets/icons.ts is stale: run `npm run build:icons` and commit the result.')
    process.exitCode = 1
    return
  }
  await writeFile(ICONS_MODULE, fresh)
  console.log('src/assets/icons.ts written')
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) await main()
